const msg = $json.message || {};
const chatId = msg.chat ? msg.chat.id : null;
const rawText = (msg.text || "").trim();
const lowerText = rawText.toLowerCase();

// بيانات العميل والتاريخ
const firstName = msg.chat ? (msg.chat.first_name || "") : "";
const lastName = msg.chat ? (msg.chat.last_name || "") : "";
const customerName = `${firstName} ${lastName}`.trim() || "غير محدد";
const username = msg.chat ? (msg.chat.username || "لا يوجد") : "لا يوجد";
const dateTime = new Date().toLocaleString("ar-EG", { timeZone: "Africa/Cairo" });

let isStart = false;
let isTrackOrder = false;
let isRepeatOrder = false;
let isRating = false;
let needsTranscription = false;
let voiceFileId = null;
let finalText = rawText;
let ratingScore = "غير محدد";

// 1. التعامل مع الرسائل الصوتية
if (msg.voice && msg.voice.file_id) {
  needsTranscription = true;
  voiceFileId = msg.voice.file_id;
}

// 2. الموقع المباشر من تليجرام
if (msg.location && typeof msg.location.latitude !== 'undefined') {
  finalText = `📍 موقع التوصيل المحدد: https://maps.google.com/?q=${msg.location.latitude},${msg.location.longitude}`;
}

// 3. تحديد المسارات (Routes)

// أ) مسار بداية البوت (Start)
if (rawText === "/start") {
  isStart = true;
}

// ب) مسار تكرار آخر أوردر (Repeat Order)
else if (
  lowerText === "/repeat" ||
  lowerText.includes("كرر") ||
  lowerText.includes("تكرار") ||
  lowerText.includes("إعادة") ||
  lowerText.includes("نفس الأوردر") ||
  lowerText.includes("نفس الطلب") ||
  lowerText.includes("اعادة الطلب")
) {
  isRepeatOrder = true;
}

// ج) مسار تتبع الأوردر (Track Order)
else if (
  lowerText === "/track" ||
  lowerText.includes("تتبع") ||
  lowerText.includes("متابعة الأوردر") ||
  lowerText.includes("وين الأوردر") ||
  lowerText.includes("فين الأوردر") ||
  lowerText.includes("الطلب وصل فين")
) {
  isTrackOrder = true;
}

// د) مسار التقييم (Rating)
else {
  const containsStars = /[\u2b50⭐]/.test(rawText);
  const ratingKeywords = ["تقييم", "نجوم", "نجمة", "من 5", "من5", "1/5", "2/5", "3/5", "4/5", "5/5", "من 10", "10/10"];
  const containsRatingKeyword = ratingKeywords.some(keyword => lowerText.includes(keyword));
  const isSingleRatingNumber = /^[1-5]$/.test(rawText);

  if (containsStars || containsRatingKeyword || isSingleRatingNumber) {
    isRating = true;

    // استخراج قيمة التقييم الرقمية
    const scoreMatch = rawText.match(/([1-5])\s*(من|\/|\s*نجوم|\s*نجمة)?/);
    if (scoreMatch) {
      ratingScore = scoreMatch[1];
    } else if (containsStars) {
      const starCount = (rawText.match(/[\u2b50⭐]/g) || []).length;
      if (starCount > 0) ratingScore = Math.min(starCount, 5).toString();
    }
  }
}

return [{
  json: {
    message: { ...msg, text: finalText },
    chat_id: chatId,
    customer_name: customerName,
    username: username,
    date_time: dateTime,
    rating_score: ratingScore,
    isStart,
    isTrackOrder,
    isRepeatOrder,
    isRating,
    needsTranscription,
    voiceFileId
  }
}];

const transcript = $json.text || ($json.data && $json.data.text) || "";
const original = $('Prepare Input').item.json;
return [{
  json: {
    ...original,
    message: { ...original.message, text: transcript },
    needsTranscription: false
  }
}];

